UPDATE identity
SET status = 'FAILED',
failure_reason = #{failureReason}
WHERE identity_verification_id = #{identityVerificationId}
AND status = 'REQUESTED'

UPDATE identity
SET status = 'USED',
used_at = NOW()
WHERE identity_verification_id = #{identityVerificationId}
AND user_id = #{userId}
AND purpose = #{purpose}
AND status = 'VERIFIED'
AND expires_at > NOW()
AND used_at IS NULL
